using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace ScreenDock {
 public partial class Map {
  public bool DragEnabled;public Action Changed;Display dragTarget;Point dragStart;Native.Mode dragMode;float dragScale,lastScale;PointF dragOrigin,lastOrigin;
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(!DragEnabled||e.Button!=MouseButtons.Left)return;var d=hit.Where(x=>x.Key.Contains(e.Location)).Select(x=>x.Value).FirstOrDefault();if(d==null||lastScale<=0)return;Selected=d.Device;if(Pick!=null)Pick(d);dragTarget=d;dragStart=e.Location;dragMode=d.Mode;dragScale=lastScale;dragOrigin=lastOrigin;Capture=true;Invalidate();}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragTarget==null)return;var m=dragMode;m.x+=(int)Math.Round((e.X-dragStart.X)/dragScale);m.y+=(int)Math.Round((e.Y-dragStart.Y)/dragScale);dragTarget.Mode=m;Invalidate();}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(dragTarget==null)return;var d=dragTarget;bool moved=Math.Abs(e.X-dragStart.X)+Math.Abs(e.Y-dragStart.Y)>4;if(!moved)d.Mode=dragMode;else DisplayLayout.Snap(d,Displays);dragTarget=null;Capture=false;Invalidate();if(moved&&Changed!=null)Changed();}
  protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(dragTarget!=null&&!Capture){dragTarget.Mode=dragMode;dragTarget=null;Invalidate();}}
 }
 public static class DisplayLayout {
  public static Rectangle Bounds(Display d){return new Rectangle(d.Mode.x,d.Mode.y,(int)d.Mode.width,(int)d.Mode.height);}
  public static List<Display> Copy(IEnumerable<Display> source){return source.Select(d=>new Display{Device=d.Device,Identity=d.Identity,Name=d.Name,Number=d.Number,Active=d.Active,Primary=d.Primary,Mode=d.Mode}).ToList();}
  public static void Snap(Display moving,List<Display> all){var others=all.Where(x=>x.Active&&x!=moving).ToList();if(others.Count==0)return;var m=moving.Mode;var candidates=new List<Point>();foreach(var other in others){var r=Bounds(other);int w=(int)m.width,h=(int)m.height;int y=Math.Max(r.Top-h+1,Math.Min(m.y,r.Bottom-1)),x=Math.Max(r.Left-w+1,Math.Min(m.x,r.Right-1));int tolerance=80;if(Math.Abs(y-r.Top)<tolerance)y=r.Top;else if(Math.Abs(y-(r.Bottom-h))<tolerance)y=r.Bottom-h;if(Math.Abs(x-r.Left)<tolerance)x=r.Left;else if(Math.Abs(x-(r.Right-w))<tolerance)x=r.Right-w;candidates.Add(new Point(r.Left-w,y));candidates.Add(new Point(r.Right,y));candidates.Add(new Point(x,r.Top-h));candidates.Add(new Point(x,r.Bottom));}var valid=candidates.Where(p=>!others.Any(d=>new Rectangle(p.X,p.Y,(int)m.width,(int)m.height).IntersectsWith(Bounds(d)))).OrderBy(p=>Math.Pow(p.X-(double)m.x,2)+Math.Pow(p.Y-(double)m.y,2)).ToList();if(valid.Count==0)return;m.x=valid[0].X;m.y=valid[0].Y;moving.Mode=m;}
  public static Dictionary<string,Native.Mode> Plan(List<Display> displays){var active=displays.Where(x=>x.Active).ToList();if(active.Count(x=>x.Primary)!=1)throw new Exception("无法确认唯一主显示器。");foreach(var d in active)if(d.Mode.width==0||d.Mode.height==0)throw new Exception("无效分辨率。");for(int i=0;i<active.Count;i++)for(int j=i+1;j<active.Count;j++)if(Bounds(active[i]).IntersectsWith(Bounds(active[j])))throw new Exception("屏幕不能重叠，请拖动后重新应用。");var reached=new HashSet<Display>{active[0]};bool progress;do{progress=false;foreach(var d in active.Where(x=>!reached.Contains(x)).ToList())if(reached.Any(x=>Touch(Bounds(d),Bounds(x)))){reached.Add(d);progress=true;}}while(progress);if(reached.Count!=active.Count)throw new Exception("屏幕边缘需相邻，请拖动屏幕吸附到其他屏幕边缘。");var primary=active.Single(x=>x.Primary).Mode;return active.ToDictionary(d=>d.Device,d=>{var m=d.Mode;m.x-=primary.x;m.y-=primary.y;m.size=220;m.extra=0;m.fields=0x20|0x80000|0x100000|0x400000|0x40000|0x80;m.form=m.form??"";m.device=m.device??"";return m;});}
  static bool Touch(Rectangle a,Rectangle b){return ((a.Right==b.Left||a.Left==b.Right)&&Math.Max(a.Top,b.Top)<Math.Min(a.Bottom,b.Bottom))||((a.Top==b.Bottom||a.Bottom==b.Top)&&Math.Max(a.Left,b.Left)<Math.Min(a.Right,b.Right));}
  public static List<Native.Mode> Modes(Display d){var result=new List<Native.Mode>();for(int i=0;i<10000;i++){var m=Native.NewMode();if(!Native.EnumDisplaySettings(d.Device,i,ref m))break;if(m.width>0&&m.height>0&&m.frequency>1&&m.bits==d.Mode.bits&&m.orientation==d.Mode.orientation&&m.flags==d.Mode.flags)result.Add(m);}return result.GroupBy(m=>m.width+"x"+m.height+"@"+m.frequency).Select(g=>g.First()).OrderByDescending(m=>(long)m.width*m.height).ThenByDescending(m=>m.frequency).ToList();}
 }
 public class LayoutEditor : Form {
  List<Display> original,preview;Map map=new Map();ComboBox device=new ComboBox(),resolution=new ComboBox(),rate=new ComboBox();Label hint=new Label();Button apply=new Button();Dictionary<string,List<Native.Mode>> available=new Dictionary<string,List<Native.Mode>>();bool loading,applying;bool demo;
  Display Current{get{return device.SelectedIndex<0?null:preview.Where(x=>x.Active).ElementAt(device.SelectedIndex);}}
  public LayoutEditor(List<Display> displays,bool demoMode){demo=demoMode;original=DisplayLayout.Copy(displays);preview=DisplayLayout.Copy(displays);Text="屏幕位置、分辨率和刷新率";ClientSize=new Size(920,610);MinimumSize=new Size(800,620);StartPosition=FormStartPosition.CenterParent;Font=Art.Font(18);BackColor=Color.White;
   map.Bounds=new Rectangle(20,20,880,345);map.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom;map.Displays=preview;map.DragEnabled=true;map.Pick=d=>{device.SelectedIndex=preview.Where(x=>x.Active).ToList().FindIndex(x=>x==d);};map.Changed=()=>hint.Text="布局已修改（尚未应用）；可继续拖动或选择分辨率。";Controls.Add(map);
   var row=new FlowLayoutPanel{Bounds=new Rectangle(20,385,880,55),Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom};foreach(var c in new[]{device,resolution,rate}){c.DropDownStyle=ComboBoxStyle.DropDownList;c.Width=c==device?280:c==resolution?260:180;row.Controls.Add(c);}Controls.Add(row);
   rate.FormattingEnabled=true;rate.Format+=delegate(object sender,ListControlConvertEventArgs e){e.Value=e.ListItem+" Hz";};
   hint.Bounds=new Rectangle(20,451,880,70);hint.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom;hint.Text="拖动屏幕调整位置，松手自动吸附。只有点击应用才修改 Windows。";Controls.Add(hint);
   var reset=new Button{Text="重置预览",Bounds=new Rectangle(620,547,130,40),Anchor=AnchorStyles.Bottom|AnchorStyles.Right};apply.Text="应用更改";apply.Bounds=new Rectangle(765,547,135,40);apply.Anchor=AnchorStyles.Bottom|AnchorStyles.Right;Controls.Add(reset);Controls.Add(apply);reset.Click+=delegate{preview=DisplayLayout.Copy(original);map.Displays=preview;SelectDevice();map.Invalidate();hint.Text="已重置预览，系统设置未改变。";};apply.Click+=delegate{ApplyChanges();};
   foreach(var d in preview.Where(x=>x.Active)){device.Items.Add("屏幕 "+d.Number+" · "+d.Name);available[d.Device]=demo?new List<Native.Mode>{d.Mode}:DisplayLayout.Modes(d);}device.SelectedIndexChanged+=delegate{SelectDevice();};resolution.SelectedIndexChanged+=delegate{if(!loading)SelectResolution();};rate.SelectedIndexChanged+=delegate{if(!loading)SelectRate();};if(device.Items.Count>0)device.SelectedIndex=0;else apply.Enabled=false;
   FormClosing+=delegate(object s,FormClosingEventArgs e){if(applying)e.Cancel=true;};
  }
  void SelectDevice(){var d=Current;if(d==null)return;loading=true;map.Selected=d.Device;resolution.Items.Clear();foreach(var m in available[d.Device]){string text=m.width+" × "+m.height;if(!resolution.Items.Contains(text))resolution.Items.Add(text);}resolution.SelectedItem=d.Mode.width+" × "+d.Mode.height;FillRates(d.Mode.frequency);loading=false;map.Invalidate();}
  void FillRates(uint preferred){rate.Items.Clear();var d=Current;if(d==null)return;foreach(var m in available[d.Device].Where(x=>x.width+" × "+x.height==(string)resolution.SelectedItem))rate.Items.Add(m.frequency);if(rate.Items.Contains(preferred))rate.SelectedItem=preferred;else if(rate.Items.Count>0)rate.SelectedIndex=0;rate.Enabled=rate.Items.Count>0;resolution.Enabled=resolution.Items.Count>0;}
  void SelectResolution(){var d=Current;if(d==null)return;loading=true;FillRates(d.Mode.frequency);loading=false;SelectRate();}
  void SelectRate(){var d=Current;if(d==null||rate.SelectedItem==null)return;var selected=available[d.Device].First(x=>x.width+" × "+x.height==(string)resolution.SelectedItem&&x.frequency==(uint)rate.SelectedItem);selected.x=d.Mode.x;selected.y=d.Mode.y;d.Mode=selected;map.Invalidate();hint.Text="参数已修改（尚未应用）。若屏幕重叠或有空隙，请拖动重新对齐。";}
  void ApplyChanges(){if(applying)return;Dictionary<string,Native.Mode> before=null;bool attempted=false;applying=true;apply.Enabled=false;
   try{var plan=DisplayLayout.Plan(preview);if(demo){hint.Text="演示布局验证通过，未修改真实屏幕。";return;}var fresh=Backend.Enumerate();if(fresh.Count!=original.Count||original.Any(o=>!fresh.Any(f=>f.Identity==o.Identity&&f.Device==o.Device&&f.Active==o.Active&&f.Primary==o.Primary&&f.Mode.width==o.Mode.width&&f.Mode.height==o.Mode.height&&f.Mode.x==o.Mode.x&&f.Mode.y==o.Mode.y&&f.Mode.frequency==o.Mode.frequency)))throw new Exception("屏幕状态已在外部变化，请关闭此窗口并刷新设备后重试。");foreach(var pair in plan){var m=pair.Value;int code=Native.ChangeDisplaySettingsEx(pair.Key,ref m,IntPtr.Zero,2,IntPtr.Zero);if(code!=0)throw new Exception("驱动不支持所选显示模式（"+code+"），未应用。");}before=fresh.ToDictionary(d=>d.Device,d=>d.Active?d.Mode:Backend.Disabled(d.Mode));Backend.Remember(fresh);attempted=true;Backend.Apply(plan);using(var confirm=new Confirm("已修改屏幕位置和显示参数，是否保留？")){if(confirm.ShowDialog(this)!=DialogResult.OK){Backend.Apply(before);attempted=false;hint.Text="已恢复原布局。";}else{attempted=false;original=Backend.Enumerate();preview=DisplayLayout.Copy(original);map.Displays=preview;SelectDevice();map.Invalidate();hint.Text="已保留新的屏幕位置和显示参数。";}}}
   catch(Exception ex){string error=ex.Message;if(attempted&&before!=null)try{Backend.Apply(before);error+=" 已恢复原布局。";}catch(Exception restore){error+=" 恢复失败，请使用 Windows 显示设置："+restore.Message;}MessageBox.Show(this,error,"显示设置");}
   finally{applying=false;apply.Enabled=true;}
  }
 }
 public partial class MainForm {
  void OpenLayoutEditor(){if(!PresetReady){status.Text="请等待当前检测或调节完成后，再调整布局。";return;}busy=true;SelectDisplay();try{using(var editor=new LayoutEditor(demo?displays:Backend.Enumerate(),demo))editor.ShowDialog(this);}catch(Exception ex){MessageBox.Show(this,ex.Message,"显示设置");}finally{busy=false;RefreshDisplays();}}
 }
}
